// spec: .qa/e2e/specs/add-candidate.md
// seed: tests/seed.hunter_plus.spec.ts
// Nothing is saved: the dialog is closed with «יציאה».
import { test, expect } from '@playwright/test';
import path from 'path';
import { openAddCandidate, closeAddCandidate, searchMyCandidates } from './helpers';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_plus.json') });

const CV = path.join(__dirname, '../../fixtures/qa-auto-cv-salary-range.pdf');
const digits = (v: string) => v.replace(/\D/g, '');

test.describe('«הוספת מועמד» — CV salary parsing (#344b9a)', () => {
  test('CV parsing fills «ציפיות שכר מ-/עד» from a salary range @desktop #344b9a', async ({ page }) => {
    test.setTimeout(150_000);
    // 1. Upload the CV («Expected salary: 22,000 - 26,000 NIS per month»)
    const dialog = await openAddCandidate(page);
    await expect(dialog.getByRole('heading', { name: 'קובץ קו״ח' })).toBeVisible();
    await dialog.locator('input[type="file"][accept*="pdf"]').setInputFiles(CV);

    // 2. AI parsing done
    await expect(dialog.getByText(/^מילאנו מקורות החיים/)).toBeVisible({ timeout: 120_000 });

    const from = dialog.getByRole('textbox', { name: 'ציפיות שכר מ- (₪)' });
    const to = dialog.getByRole('textbox', { name: 'ציפיות שכר עד (₪)' });
    expect(digits(await from.inputValue())).toBe('22000');
    expect(digits(await to.inputValue())).toBe('26000');

    // 3. Close → «יציאה»: not saved
    await closeAddCandidate(page, 'יציאה');
    const headings = await searchMyCandidates(page, 'Testcv');
    await expect(headings.filter({ hasText: 'QA-AUTO Salary Testcv' })).toHaveCount(0);
  });
});
